import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"Memoh Overview","description":"","frontmatter":{},"headers":[],"relativePath":"guides/overview.md","filePath":"guides/overview.md","lastUpdated":1790952322000}'),n={name:"guides/overview.md"};function s(i,e,l,h,d,c){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="memoh-overview" tabindex="-1">Memoh Overview <a class="header-anchor" href="#memoh-overview" aria-label="Permalink to &quot;Memoh Overview&quot;">​</a></h1><p>Memoh gives every bot its own cloud computer: a workspace with a real filesystem and terminal, a desktop browser you can watch and take over, and long-term memory that carries across sessions. Close your laptop; the bot keeps working.</p><p>You work with a bot by messaging it — in the Memoh app, or on Telegram, Slack, Discord, Feishu, DingTalk, WeCom, WeChat, QQ, and LINE. Every entry point reaches the same bot and the same memory.</p><p>Getting in takes a download and a Memoh Cloud sign-in. Hosted models (DeepSeek, Kimi, GPT, Claude, and more) are ready to use; to run your own keys or model service, see <a href="./quick-start.html#bring-your-own-key-byok">BYOK</a>.</p><h2 id="what-makes-memoh-different" tabindex="-1">What makes Memoh different <a class="header-anchor" href="#what-makes-memoh-different" aria-label="Permalink to &quot;What makes Memoh different&quot;">​</a></h2><ul><li><strong>A real computer, not a throwaway sandbox.</strong> Files you write and runtimes you install stay in the <a href="./container.html">workspace</a>; what you set up on Monday is still there on Friday.</li><li><strong>A screen you can see.</strong> The bot drives a real browser on a visible desktop; when it hits a login or CAPTCHA, you <a href="./browser-computer-use.html">take over the keyboard</a>, finish the step, and hand control back.</li><li><strong>It remembers.</strong> <a href="./memory.html">Long-term memory</a> works across sessions and channels; a preference you correct once should stick.</li><li><strong>It runs while you are away.</strong> <a href="./schedule.html">Scheduled tasks</a> fire on cron and deliver to your connected channels — checking on time, speaking only when something changed.</li><li><strong>Bring your own coding agent.</strong> Put Claude Code or Codex into the same workspace over <a href="./acp.html">ACP</a>, on your own subscription.</li></ul><h2 id="one-bot-per-job" tabindex="-1">One bot per job <a class="header-anchor" href="#one-bot-per-job" aria-label="Permalink to &quot;One bot per job&quot;">​</a></h2><p>Every bot has its own workspace, memory, channels, and permission boundary; bots cannot see into each other. When work genuinely splits into roles, create another bot instead of overloading one. Who can chat with a bot, read or write its files, and run commands is granted level by level in <a href="./access.html">Access Control</a> — give the level the job needs and no more.</p><h2 id="a-good-first-handoff" tabindex="-1">A good first handoff <a class="header-anchor" href="#a-good-first-handoff" aria-label="Permalink to &quot;A good first handoff&quot;">​</a></h2><p>Pick something small you already do by hand every week, and state the outcome, sources, and boundaries:</p><blockquote><p>Every Friday at 17:00, turn the links and files I sent you this week into a weekly report — grouped by theme, one line each. Save it in the workspace and post the summary to this conversation. Organize only what I sent you; never send anything to anyone else.</p></blockquote><p>The bot registers the schedule itself and delivers weekly. Start with read-only work, review a few outputs, then widen what it may write and execute — see <a href="./use-cases.html">Use Cases</a> for ready-made setups.</p><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><p><strong>Does it keep running when my computer is off?</strong></p><p>Yes. The bot runs in a cloud workspace; schedules fire and channel messages get answered either way.</p><p><strong>How many bots can I create?</strong></p><p>That depends on your plan. Each bot is independent — its own workspace, memory, and permissions — and deleting one does not affect the others.</p><p><strong>Where do my files live?</strong></p><p>In that bot&#39;s isolated container workspace (<code>/data</code>), kept across sessions and browsable under <a href="./files.html">Files</a>.</p><p><strong>Can I use my own models?</strong></p><p>Yes. Add your own API keys under Providers (see <a href="./quick-start.html#bring-your-own-key-byok">BYOK</a>); for coding agents, sign in with your own Claude Code or Codex subscription on the bot&#39;s <strong>Agent</strong> tab.</p><p><strong>Where do plan and billing questions go?</strong></p><p>The <a href="https://memoh.ai/help" target="_blank" rel="noreferrer">Help Center</a>: plans, credits, account questions, and a direct line to the Memoh team.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./quick-start.html">Quick Start</a> — from installing the app to a connected chat platform, in about fifteen minutes.</li><li><a href="./use-cases.html">Use Cases</a> — ready-to-follow scenarios that combine features to solve real problems.</li><li><a href="./working-with-bots.html">Bot</a> — configure a bot tab by tab.</li><li><a href="./../integrations/channels/">Channels</a> — per-platform setup guides.</li><li><a href="https://memoh.ai/help" target="_blank" rel="noreferrer">Help Center</a> — plans, billing, and account questions.</li></ul>',25)])])}const u=o(n,[["render",s]]);export{p as __pageData,u as default};
